1	// playwright-helpers.js
2	// Reusable utility functions for Playwright automation
3	
4	const { chromium, firefox, webkit } = require('playwright');
5	
6	/**
7	 * Parse extra HTTP headers from environment variables.
8	 * Supports two formats:
9	 * - PW_HEADER_NAME + PW_HEADER_VALUE: Single header (simple, common case)
10	 * - PW_EXTRA_HEADERS: JSON object for multiple headers (advanced)
11	 * Single header format takes precedence if both are set.
12	 * @returns {Object|null} Headers object or null if none configured
13	 */
14	function getExtraHeadersFromEnv() {
15	  const headerName = process.env.PW_HEADER_NAME;
16	  const headerValue = process.env.PW_HEADER_VALUE;
17	
18	  if (headerName && headerValue) {
19	    return { [headerName]: headerValue };
20	  }
21	
22	  const headersJson = process.env.PW_EXTRA_HEADERS;
23	  if (headersJson) {
24	    try {
25	      const parsed = JSON.parse(headersJson);
26	      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
27	        return parsed;
28	      }
29	      console.warn('PW_EXTRA_HEADERS must be a JSON object, ignoring...');
30	    } catch (e) {
31	      console.warn('Failed to parse PW_EXTRA_HEADERS as JSON:', e.message);
32	    }
33	  }
34	
35	  return null;
36	}
37	
38	/**
39	 * Launch browser with standard configuration
40	 * @param {string} browserType - 'chromium', 'firefox', or 'webkit'
41	 * @param {Object} options - Additional launch options
42	 */
43	async function launchBrowser(browserType = 'chromium', options = {}) {
44	  const defaultOptions = {
45	    headless: process.env.HEADLESS !== 'false',
46	    slowMo: process.env.SLOW_MO ? parseInt(process.env.SLOW_MO) : 0,
47	    args: ['--no-sandbox', '--disable-setuid-sandbox']
48	  };
49	  
50	  const browsers = { chromium, firefox, webkit };
51	  const browser = browsers[browserType];
52	  
53	  if (!browser) {
54	    throw new Error(`Invalid browser type: ${browserType}`);
55	  }
56	  
57	  return await browser.launch({ ...defaultOptions, ...options });
58	}
59	
60	/**
61	 * Create a new page with viewport and user agent
62	 * @param {Object} context - Browser context
63	 * @param {Object} options - Page options
64	 */
65	async function createPage(context, options = {}) {
66	  const page = await context.newPage();
67	  
68	  if (options.viewport) {
69	    await page.setViewportSize(options.viewport);
70	  }
71	  
72	  if (options.userAgent) {
73	    await page.setExtraHTTPHeaders({
74	      'User-Agent': options.userAgent
75	    });
76	  }
77	  
78	  // Set default timeout
79	  page.setDefaultTimeout(options.timeout || 30000);
80	  
81	  return page;
82	}
83	
84	/**
85	 * Smart wait for page to be ready
86	 * @param {Object} page - Playwright page
87	 * @param {Object} options - Wait options
88	 */
89	async function waitForPageReady(page, options = {}) {
90	  const waitOptions = {
91	    waitUntil: options.waitUntil || 'networkidle',
92	    timeout: options.timeout || 30000
93	  };
94	  
95	  try {
96	    await page.waitForLoadState(waitOptions.waitUntil, { 
97	      timeout: waitOptions.timeout 
98	    });
99	  } catch (e) {
100	    console.warn('Page load timeout, continuing...');
101	  }
102	  
103	  // Additional wait for dynamic content if selector provided
104	  if (options.waitForSelector) {
105	    await page.waitForSelector(options.waitForSelector, { 
106	      timeout: options.timeout 
107	    });
108	  }
109	}
110	
111	/**
112	 * Safe click with retry logic
113	 * @param {Object} page - Playwright page
114	 * @param {string} selector - Element selector
115	 * @param {Object} options - Click options
116	 */
117	async function safeClick(page, selector, options = {}) {
118	  const maxRetries = options.retries || 3;
119	  const retryDelay = options.retryDelay || 1000;
120	  
121	  for (let i = 0; i < maxRetries; i++) {
122	    try {
123	      await page.waitForSelector(selector, { 
124	        state: 'visible',
125	        timeout: options.timeout || 5000 
126	      });
127	      await page.click(selector, {
128	        force: options.force || false,
129	        timeout: options.timeout || 5000
130	      });
131	      return true;
132	    } catch (e) {
133	      if (i === maxRetries - 1) {
134	        console.error(`Failed to click ${selector} after ${maxRetries} attempts`);
135	        throw e;
136	      }
137	      console.log(`Retry ${i + 1}/${maxRetries} for clicking ${selector}`);
138	      await page.waitForTimeout(retryDelay);
139	    }
140	  }
141	}
142	
143	/**
144	 * Safe text input with clear before type
145	 * @param {Object} page - Playwright page
146	 * @param {string} selector - Input selector
147	 * @param {string} text - Text to type
148	 * @param {Object} options - Type options
149	 */
150	async function safeType(page, selector, text, options = {}) {
151	  await page.waitForSelector(selector, { 
152	    state: 'visible',
153	    timeout: options.timeout || 10000 
154	  });
155	  
156	  if (options.clear !== false) {
157	    await page.fill(selector, '');
158	  }
159	  
160	  if (options.slow) {
161	    await page.type(selector, text, { delay: options.delay || 100 });
162	  } else {
163	    await page.fill(selector, text);
164	  }
165	}
166	
167	/**
168	 * Extract text from multiple elements
169	 * @param {Object} page - Playwright page
170	 * @param {string} selector - Elements selector
171	 */
172	async function extractTexts(page, selector) {
173	  await page.waitForSelector(selector, { timeout: 10000 });
174	  return await page.$$eval(selector, elements => 
175	    elements.map(el => el.textContent?.trim()).filter(Boolean)
176	  );
177	}
178	
179	/**
180	 * Take screenshot with timestamp
181	 * @param {Object} page - Playwright page
182	 * @param {string} name - Screenshot name
183	 * @param {Object} options - Screenshot options
184	 */
185	async function takeScreenshot(page, name, options = {}) {
186	  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
187	  const filename = `${name}-${timestamp}.png`;
188	  
189	  await page.screenshot({
190	    path: filename,
191	    fullPage: options.fullPage !== false,
192	    ...options
193	  });
194	  
195	  console.log(`Screenshot saved: ${filename}`);
196	  return filename;
197	}
198	
199	/**
200	 * Handle authentication
201	 * @param {Object} page - Playwright page
202	 * @param {Object} credentials - Username and password
203	 * @param {Object} selectors - Login form selectors
204	 */
205	async function authenticate(page, credentials, selectors = {}) {
206	  const defaultSelectors = {
207	    username: 'input[name="username"], input[name="email"], #username, #email',
208	    password: 'input[name="password"], #password',
209	    submit: 'button[type="submit"], input[type="submit"], button:has-text("Login"), button:has-text("Sign in")'
210	  };
211	  
212	  const finalSelectors = { ...defaultSelectors, ...selectors };
213	  
214	  await safeType(page, finalSelectors.username, credentials.username);
215	  await safeType(page, finalSelectors.password, credentials.password);
216	  await safeClick(page, finalSelectors.submit);
217	  
218	  // Wait for navigation or success indicator
219	  await Promise.race([
220	    page.waitForNavigation({ waitUntil: 'networkidle' }),
221	    page.waitForSelector(selectors.successIndicator || '.dashboard, .user-menu, .logout', { timeout: 10000 })
222	  ]).catch(() => {
223	    console.log('Login might have completed without navigation');
224	  });
225	}
226	
227	/**
228	 * Scroll page
229	 * @param {Object} page - Playwright page
230	 * @param {string} direction - 'down', 'up', 'top', 'bottom'
231	 * @param {number} distance - Pixels to scroll (for up/down)
232	 */
233	async function scrollPage(page, direction = 'down', distance = 500) {
234	  switch (direction) {
235	    case 'down':
236	      await page.evaluate(d => window.scrollBy(0, d), distance);
237	      break;
238	    case 'up':
239	      await page.evaluate(d => window.scrollBy(0, -d), distance);
240	      break;
241	    case 'top':
242	      await page.evaluate(() => window.scrollTo(0, 0));
243	      break;
244	    case 'bottom':
245	      await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
246	      break;
247	  }
248	  await page.waitForTimeout(500); // Wait for scroll animation
249	}
250	
251	/**
252	 * Extract table data
253	 * @param {Object} page - Playwright page
254	 * @param {string} tableSelector - Table selector
255	 */
256	async function extractTableData(page, tableSelector) {
257	  await page.waitForSelector(tableSelector);
258	  
259	  return await page.evaluate((selector) => {
260	    const table = document.querySelector(selector);
261	    if (!table) return null;
262	    
263	    const headers = Array.from(table.querySelectorAll('thead th')).map(th => 
264	      th.textContent?.trim()
265	    );
266	    
267	    const rows = Array.from(table.querySelectorAll('tbody tr')).map(tr => {
268	      const cells = Array.from(tr.querySelectorAll('td'));
269	      if (headers.length > 0) {
270	        return cells.reduce((obj, cell, index) => {
271	          obj[headers[index] || `column_${index}`] = cell.textContent?.trim();
272	          return obj;
273	        }, {});
274	      } else {
275	        return cells.map(cell => cell.textContent?.trim());
276	      }
277	    });
278	    
279	    return { headers, rows };
280	  }, tableSelector);
281	}
282	
283	/**
284	 * Wait for and dismiss cookie banners
285	 * @param {Object} page - Playwright page
286	 * @param {number} timeout - Max time to wait
287	 */
288	async function handleCookieBanner(page, timeout = 3000) {
289	  const commonSelectors = [
290	    'button:has-text("Accept")',
291	    'button:has-text("Accept all")',
